// Política de identidad del usuario analista: puede leer informes y listar el bucket, y nada más.
export const policy = {
  Version: "2012-10-17",
  Statement: [
    { Sid: "AccesoTotalS3", Effect: "Allow", Action: "s3:*", Resource: "*" },
  ],
};

solution.code:
export const policy = {
  Version: "2012-10-17",
  Statement: [
    {
      Sid: "LeerInformes",
      Effect: "Allow",
      Action: "s3:GetObject",
      Resource: "arn:aws:s3:::amzn-s3-demo-bucket-informes/*",
    },
    {
      Sid: "ListarBucket",
      Effect: "Allow",
      Action: "s3:ListBucket",
      Resource: "arn:aws:s3:::amzn-s3-demo-bucket-informes",
    },
    {
      Sid: "DenegarConfidencial",
      Effect: "Deny",
      Action: "s3:*",
      Resource: "arn:aws:s3:::amzn-s3-demo-bucket-informes/confidencial/*",
    },
  ],
};

