assert.strictEqual(decide("s3:PutObject", "arn:aws:s3:::amzn-s3-demo-bucket-informes/2026/ventas.csv"), "ImplicitDeny");

const decide = (action: string, resource: string) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/analista", accountId: "123456789012" },
