for (const action of ["s3:PutObject", "s3:DeleteObject", "s3:GetObjectAcl"]) {
  assert.strictEqual(decide(action, "arn:aws:s3:::amzn-s3-demo-bucket-informes/confidencial/nominas.csv"), "ExplicitDeny", action + " sobre confidencial/ debe denegarse de forma explícita");
}

