assert.strictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-otro/2026/ventas.csv"), "ImplicitDeny");
assert.strictEqual(decide("s3:ListBucket", "arn:aws:s3:::amzn-s3-demo-bucket-otro"), "ImplicitDeny");

const decide = (action: string, resource: string) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/analista", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
    },
    identityPolicies: [policy],
  }).decision;
const casos: [string, string][] = [
  ["s3:DeleteObject", "arn:aws:s3:::amzn-s3-demo-bucket-informes/2026/ventas.csv"],
  ["s3:DeleteBucket", "arn:aws:s3:::amzn-s3-demo-bucket-informes"],
  ["s3:GetBucketPolicy", "arn:aws:s3:::amzn-s3-demo-bucket-informes"],
  ["s3:PutBucketPolicy", "arn:aws:s3:::amzn-s3-demo-bucket-informes"],
  ["iam:CreateUser", "arn:aws:iam::123456789012:user/nuevo"],
  ["ec2:RunInstances", "arn:aws:ec2:eu-west-1:123456789012:instance/*"],
];
for (const [action, resource] of casos) {
  assert.strictEqual(decide(action, resource), "ImplicitDeny", action + " debe quedar denegada por omisión");
}
